/**
 * 부모창 업무처리번호 여부로 신규, 수정 설정
 */
scwin.setTrJob = function() {

	//----W-Craft WebSquare 변환 확인: Provider----//
    var parentWin = frame.Provider("../");
    if (parentWin.scwin.vBzProcsNo.length > 0) {
        scwin.TR_JOB = "U";
        scwin.vBzProcsNo = parentWin.scwin.vBzProcsNo;
    } else {
        scwin.TR_JOB = "I";
    }
};



/**
 * 콤보박스 값 설정
 */
$c.elw.fn_searchCode = function() {
    var arrCid = [{
        cid: "ONECOM_APPL_RSN_CD",
        cnm: "cmb_ONECOM_APPL_RSN_CD"
    }, {
        cid: "SKIL_VALU_PROG_STAT_CD",
        cnm: "cmb_SKIL_VALU_PROG_STAT_CD"
    }, {
        cid: "SKIL_VALU_GRD_CD",
        cnm: "cmb_SKIL_VALU_GRD_CD1"
    }, {
        cid: "SKIL_VALU_GRD_CD",
        cnm: "cmb_SKIL_VALU_GRD_CD2"
    }, {
        cid: "SPECY_VALU_IND_CLSS_CD",
        cnm: "cmb_SPECY_VALU_IND_CLSS_CD"
    }, {
        cid: "SPECY_VALU_IND_CLSS_CD",
        cnm: "cmb_SPECY_VALU_IND_CLSS_CD2"
    }, {
        cid: "SPECY_VALU_SKIL_CLSS_CD",
        cnm: "cmb_SPECY_VALU_SKIL_CLSS_CD"
    }, {
        cid: "SPECY_VALU_SKIL_CLSS_CD",
        cnm: "cmb_SPECY_VALU_SKIL_CLSS_CD2"
    }];
    var objCod;
    var url = "/CodeAction.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='ONECOM_APPL_RSN_CD','SKIL_VALU_PROG_STAT_CD','SPECY_VALU_INST_CD','SKIL_VALU_GRD_CD', 'SPECY_VALU_IND_CLSS_CD', 'SPECY_VALU_SKIL_CLSS_CD'";
    dts_Cod.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: reset----//
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {

	//----W-Craft WebSquare 변환 확인: getElementById----//
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod == null) {
            alert(arrCid[i].cnm);
        }
        strCbd = "^ ";
        if (i == 0) strCbd = "^직접입력";
        for (j = 1; j <= dts_Cod.CountRow; j++) {

	//----W-Craft WebSquare 변환 확인: NameValue----//
            if (dts_Cod.NameValue(j, "CD_ENG_NM") == arrCid[i].cid) {

	//----W-Craft WebSquare 변환 확인: NameValue----//
                var cmbValue = dts_Cod.NameValue(j, "VALUE");

	//----W-Craft WebSquare 변환 확인: NameValue----//
                var cmbText = dts_Cod.NameValue(j, "TEXT");
                strCbd = strCbd + (strCbd == "" ? "" : ",") + cmbValue + "^" + cmbText;
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_grdSearchCode = function() {
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='SPECY_VALU_INST_CD'";
    dts_Cod.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: reset----//
    dts_Cod.reset();
    strCbdReason = "' ':"; //초기값

    var strCbdReason = "";
    for (k = 1; k <= dts_Cod.CountRow; k++) {

	//----W-Craft WebSquare 변환 확인: NameValue----//
        strCbdReason = strCbdReason + (strCbdReason == "" ? "" : ",") + dts_Cod.NameValue(k, "VALUE") + ":" + dts_Cod.NameValue(k, "TEXT");

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

    } /*ORG SRC: grd_ExcInst.ColumnProp('SPECY_VALU_INST_CD', 'Data') = strCbdReason;*/ X = strCbdReason;
    strCbdReason = "";
    var url = "/lstinvstg/KsqSkilValu.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=getSpecyValuLeacComList&inputMessageId=SPECY_VALU_INOUT";
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_GrdCdList.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_GrdCdList.Reset();
    for (k = 1; k <= dts_GrdCdList.CountRow; k++) {

	//----W-Craft WebSquare 변환 확인: NameValue----//
        strCbdReason = strCbdReason + (strCbdReason == "" ? "" : ",") + dts_GrdCdList.NameValue(k, "VALUE") + ":" + dts_GrdCdList.NameValue(k, "TEXT");

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

    } /*ORG SRC: grd_LeadCom.ColumnProp('LEADCOM_MBR_NO', 'Data') = strCbdReason;*/ X = strCbdReason;
};


/**
 * 유효성 체크
 */
$c.en.fn_CheckForm = function() {
    var comNm = $c.ut.trim($c.stf.getObjectValue(txb_COM_NM));
    var coreValuObjNm = $c.ut.trim($c.stf.getObjectValue(txb_CORE_VALU_OBJ_NM));
    var assgnApplDd = $c.stf.getObjectValue(edt_ASSGN_APPL_DD);
    if (comNm == "") {
        alert("회사명은 필수로 입력하여야 합니다");

	//----W-Craft WebSquare 변환 확인: focus----//
        txb_COM_NM.focus();
        return false;
    }
    if (assgnApplDd == "") {
        alert("배정신청일은 필수로 입력하여야 합니다");

	//----W-Craft WebSquare 변환 확인: focus----//
        edt_ASSGN_APPL_DD.focus();
        return false;
    }
    if (!scwin.dateCheck(edt_SKIL_VALU_ASSGN_DD, "배정일")) {
        return false;
    }
    var valuInstApplCnt = $c.stf.getObjectValue(rdo_VALU_INST_APPL_CNT);
    var oneComApplRsnCd = $c.stf.getObjectValue(cmb_ONECOM_APPL_RSN_CD);
    var oneComApplRsnNm = $c.stf.getObjectValue(txb_ONECOM_APPL_RSN_NM);
    var valuStrtDd = $c.stf.getObjectValue(edt_VALU_STRT_DD);
    var valuStrtDd2 = $c.stf.getObjectValue(edt_VALU_STRT_DD2);
    var skilValuInstCd1 = $c.stf.getObjectValue(cmb_SKIL_VALU_INST_CD1);
    var skilValuInstNm1 = $c.ut.trim($c.stf.getObjectValue(txb_SKIL_VALU_INST_NM1));
    if (valuStrtDd != "") {
        if (skilValuInstCd1 == "" && skilValuInstNm1 == "") {

	//----W-Craft WebSquare 변환 확인: focus----//
            cmb_SKIL_VALU_INST_CD1.focus();
            alert("평가시작일을 입력하였다면 평가기관1을 입력하여야 합니다");
            return false;
        }
    }
    if (valuStrtDd2 != "") {
        if (valuInstApplCnt == 2) {
            var skilValuInstCd2 = $c.stf.getObjectValue(cmb_SKIL_VALU_INST_CD2);
            var skilValuInstNm2 = $c.ut.trim($c.stf.getObjectValue(txb_SKIL_VALU_INST_NM2));
            if (skilValuInstCd2 == "" && skilValuInstNm2 == "") {

	//----W-Craft WebSquare 변환 확인: focus----//
                cmb_SKIL_VALU_INST_CD2.focus();
                alert("평가시작일2을 입력하였다면 평가기관2를 입력하여야 합니다");
                return false;
            }
        }
    }
    var valuRsltDd1 = $c.stf.getObjectValue(edt_VALU_RSLT_DD1);
    var valuRsltDd2 = $c.stf.getObjectValue(edt_VALU_RSLT_DD2);
    if (valuRsltDd1 != "" && valuStrtDd > valuRsltDd1) {
        alert("평가결과일1은 평가시작일 이후여야 합니다");

	//----W-Craft WebSquare 변환 확인: focus----//
        edt_VALU_RSLT_DD1.focus();
        return false;
    }
    if (valuRsltDd2 != "" && valuStrtDd2 > valuRsltDd2) {
        alert("평가결과일2은 평가시작일2 이후여야 합니다");

	//----W-Craft WebSquare 변환 확인: focus----//
        edt_VALU_RSLT_DD2.focus();
        return false;
    }
    var skilValuProgStatCd = $c.stf.getObjectValue(cmb_SKIL_VALU_PROG_STAT_CD);
    var assgnSuspnDd = $c.stf.getObjectValue(edt_ASSGN_SUSPN_DD);
    /*
    if(skilValuProgStatCd == "04" && assgnSuspnDd == ""){
    	alert("진행상태가 '배정중단'인 경우 배정중단일을 입력하여야 합니다");

	//----W-Craft WebSquare 변환 확인: focus----//
    	edt_ASSGN_SUSPN_DD.focus();
    	return false;
    }	
    */

	//----W-Craft WebSquare 변환 확인: ValueOfIndex----//
    var skilValuInstText1 = cmb_SKIL_VALU_INST_CD1.ValueOfIndex("TEXT", cmb_SKIL_VALU_INST_CD1.Index);

	//----W-Craft WebSquare 변환 확인: ValueOfIndex----//
    var skilValuInstText2 = cmb_SKIL_VALU_INST_CD2.ValueOfIndex("TEXT", cmb_SKIL_VALU_INST_CD2.Index);
    if (skilValuInstText1.indexOf("제척") > -1) {
        alert("평가기관에 제척기관으로 선택된 기관은 저장할 수 없습니다");

	//----W-Craft WebSquare 변환 확인: focus----//
        cmb_SKIL_VALU_INST_CD1.focus();
        return false;
    }
    if (skilValuInstText2.indexOf("제척") > -1) {
        alert("평가기관에 제척기관으로 선택된 기관은 저장할 수 없습니다");

	//----W-Craft WebSquare 변환 확인: focus----//
        cmb_SKIL_VALU_INST_CD2.focus();
        return false;
    }
    /*
    if(!checkFileSize()){
    	return false;
    }
    */
    if (!$c.stf.checkMaxLength(txb_COM_NM, txb_COM_NM.maxLength, "법인명")) return false;
    if (!$c.stf.checkMaxLength(txb_REP_NM, txb_REP_NM.maxLength, "대표자명")) return false;
    if (!$c.stf.checkMaxLength(txb_SPECY_VALU_COM_TP_VAL, txb_SPECY_VALU_COM_TP_VAL.maxLength, "기업형태")) return false;
    if (!$c.stf.checkMaxLength(txb_TEL_NO, txb_TEL_NO.maxLength, "연락처 Tel.")) return false;
    if (!$c.stf.checkMaxLength(txb_ADDR, txb_ADDR.maxLength, "본사주소")) return false;
    if (!$c.stf.checkMaxLength(txb_DTL_ADDR, txb_DTL_ADDR.maxLength, "본사주소 상세")) return false;
    if (!$c.stf.checkMaxLength(txb_MAINTR_BK_NM, txb_MAINTR_BK_NM.maxLength, "주거래은행")) return false;
    if (!$c.stf.checkMaxLength(txb_FAX_NO, txb_FAX_NO.maxLength, "연락처 Fax.")) return false;
    if (!$c.stf.checkMaxLength(txb_SPECY_VALU_MAJ_PROD_VAL1, txb_SPECY_VALU_MAJ_PROD_VAL1.maxLength, "제1사업 주요제품및 상품")) return false;
    if (!$c.stf.checkMaxLength(txb_SPECY_VALU_MAJ_PROD_VAL2, txb_SPECY_VALU_MAJ_PROD_VAL2.maxLength, "제2사업 주요제품및 상품")) return false;
    if (!$c.stf.checkMaxLength(txb_SPECY_VALU_MAJ_PROD_VAL3, txb_SPECY_VALU_MAJ_PROD_VAL3.maxLength, "제3사업 주요제품및 상품")) return false;
    if (!$c.stf.checkMaxLength(txb_APCT_NM, txb_APCT_NM.maxLength, "신청자 이름")) return false;
    if (!$c.stf.checkMaxLength(txb_APCT_TEL_NO, txb_APCT_TEL_NO.maxLength, "신청자 연락처")) return false;
    if (!$c.stf.checkMaxLength(txb_APCT_EMAIL, txb_APCT_EMAIL.maxLength, "신청자 이메일")) return false;
    if (!$c.stf.checkMaxLength(txb_CORE_VALU_OBJ_NM, txb_CORE_VALU_OBJ_NM.maxLength, "핵심평가대상")) return false;
    if (!$c.stf.checkMaxLength(txb_MAJ_PROD_NM, txb_MAJ_PROD_NM.maxLength, "주요 제품 및 상품")) return false;
    if (!$c.stf.checkMaxLength(txb_ONECOM_APPL_RSN_NM, txb_ONECOM_APPL_RSN_NM.maxLength, "특례대상여부 직접입력")) return false;
    if (!$c.stf.checkMaxLength(txb_ADD_EXC_INST_NM, txb_ADD_EXC_INST_NM.maxLength, "그 외 체척기관")) return false;
    if (!$c.stf.checkMaxLength(txa_REMK, 2000, "주관사 입력비고")) return false;
    if (!$c.stf.checkMaxLength(txa_INSIDE_REMK, 300, "내부용 비고")) return false;
    if (!$c.stf.checkMaxLength(txb_SKIL_VALU_INST_NM1, txb_SKIL_VALU_INST_NM1.maxLength, "평가기관1 직접입력")) return false;
    if (!$c.stf.checkMaxLength(txb_SKIL_VALU_INST_NM2, txb_SKIL_VALU_INST_NM2.maxLength, "평가기관2 직접입력")) return false;
    if (!$c.stf.checkMaxLength(txb_VALU_INST_CHRG_NM, txb_VALU_INST_CHRG_NM.maxLength, "평가기관1 담당자")) return false;
    if (!$c.stf.checkMaxLength(txb_VALU_INST_CHRG_NM2, txb_VALU_INST_CHRG_NM2.maxLength, "평가기관2 담당자")) return false;
    if (!$c.stf.checkMaxLength(txb_VALU_INST_TEL_NO, txb_VALU_INST_TEL_NO.maxLength, "평가기관1 연락처")) return false;
    if (!$c.stf.checkMaxLength(txb_VALU_INST_TEL_NO2, txb_VALU_INST_TEL_NO2.maxLength, "평가기관2 연락처")) return false;
    if (!$c.stf.checkMaxLength(txb_VALU_INST_EMAIL, txb_VALU_INST_EMAIL.maxLength, "평가기관1 이메일")) return false;
    if (!$c.stf.checkMaxLength(txb_VALU_INST_EMAIL2, txb_VALU_INST_EMAIL2.maxLength, "평가기관2 이메일")) return false;
    if (!$c.stf.checkMaxLength(txa_EXT_OPN_VALU_RSLT_REMK, 1000, "외부 공개용 평가 결과 관련 비고")) return false;
    if (!$c.stf.checkMaxLength(txb_LIST_BROKER_NM, txb_LIST_BROKER_NM.maxLength, "주관사 기타")) return false;
    return true;
};
scwin.fn_checkGrid = function() {
    var comCd, compCdIn;
    for (var i = 1, j = dts_LeadCom.CountRow; i <= j; i++) {

	//----W-Craft WebSquare 변환 확인: NameValue----//
        comCd = dts_LeadCom.NameValue(i, "LEADCOM_MBR_NO");
        if (comCd == "") {
            alert("주관사에 빈값을 선택할수 없스니다.");
            return false;
        }
        for (var k = 1, l = dts_LeadCom.CountRow; k <= l; k++) {
            if (i == k) continue;

	//----W-Craft WebSquare 변환 확인: NameValue----//
            compCdIn = dts_LeadCom.NameValue(k, "LEADCOM_MBR_NO");
            if (comCd == compCdIn) {
                alert("동일한 주관사는 입력할 수 없습니다.");
                return false;
            }
        }
    }
    for (var i = 1, j = dts_ExecInstList.CountRow; i <= j; i++) {

	//----W-Craft WebSquare 변환 확인: NameValue----//
        comCd = dts_ExecInstList.NameValue(i, "SPECY_VALU_INST_CD");
        if (comCd == "") {
            alert("제척기관에 빈값을 선택할수 없스니다.");
            return false;
        }
        for (var k = 1, l = dts_ExecInstList.CountRow; k <= l; k++) {
            if (i == k) continue;

	//----W-Craft WebSquare 변환 확인: NameValue----//
            compCdIn = dts_ExecInstList.NameValue(k, "SPECY_VALU_INST_CD");
            if (comCd == compCdIn) {
                alert("동일한 제척기관은 입력할 수 없습니다.");
                return false;
            }
        }
    }
    return true;
};


/**
 * 저장
 */
scwin.fn_save = function() {
    scwin.TR_JOB = 'I';
    if (scwin.fn_CheckForm() && scwin.fn_checkGrid() && scwin.fncheckInstCheck()) {
        if (!$c.lce.fn_isProcess(scwin.TR_JOB)) return;
        scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);

        //alert("[bz_procs_no]"+bz_procs_no);
        if (scwin.vBzProcsNo.length != 14) {
            alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************


	//----W-Craft WebSquare 변환 확인: NameValue----//
            /*ORG SRC: dts_info.NameValue(1, "BZ_PROCS_NO") = vBzProcsNo;*/
            X = scwin.vBzProcsNo;
            scwin.fn_trs(TR_JOB_INSERT);
        }
    }
};




/**
 * 평가기관 신청수에 따른 처리
 */
scwin.fn_changeApplCnt = function() {
    var applCnt = $c.stf.getObjectValue(rdo_VALU_INST_APPL_CNT);
    var valueYn = $c.stf.getObjectValue(cmb_ONECOM_APPL_RSN_CD);
    if (valueYn == "99" && applCnt == "1") {
        alert("특례대상여부가 해당없음인 경우 1사 선택 불가");
        $c.stf.setObjectValue(rdo_VALU_INST_APPL_CNT, "2");

	//----W-Craft WebSquare 변환 확인: Reset----//
        rdo_VALU_INST_APPL_CNT.Reset();
        return;
    }
    if (applCnt == "1") {
        cmb_SKIL_VALU_INST_CD2.enable2 = false;
        cmb_SKIL_VALU_GRD_CD2.enable2 = false;
        edt_VALU_RSLT_DD2.setDisabled(true);
        $c.stf.setObjectValue(cmb_SKIL_VALU_INST_CD2, "");
