 */
scwin.fn_changeApplRsn = function() {
    var oneComApplRsnCd = $c.stf.getObjectValue(cmb_ONECOM_APPL_RSN_CD);
    var applCnt = $c.stf.getObjectValue(rdo_VALU_INST_APPL_CNT);
    /*
    if(oneComApplRsnCd == "99"){
    	rdo_VALU_INST_APPL_CNT.Format = "2^2사^,1^1사^Disabled";

	//----W-Craft WebSquare 변환 확인: Reset----//
    	rdo_VALU_INST_APPL_CNT.Reset();
    }else{
    	rdo_VALU_INST_APPL_CNT.Format = "2^2사^,1^1사";

	//----W-Craft WebSquare 변환 확인: Reset----//
    	rdo_VALU_INST_APPL_CNT.Reset();
    }
    */
    if (applCnt == "1" && oneComApplRsnCd == "99") {
        //1사신청인 경우 해당없음 선택불가
        alert("특례대상 여부 '해당없음'인 경우 평가기관 신청수 1사 선택불가");
        $c.stf.setObjectValue(rdo_VALU_INST_APPL_CNT, "2");
        cmb_SKIL_VALU_INST_CD2.enable2 = true;
        txb_SKIL_VALU_INST_NM2.setDisabled(true);
        cmb_SKIL_VALU_GRD_CD2.enable2 = true;
        edt_VALU_RSLT_DD2.setDisabled(false);
        return;
    }
    if (oneComApplRsnCd == "") {
        txb_ONECOM_APPL_RSN_NM.setDisabled(true);
    } else {
        txb_ONECOM_APPL_RSN_NM.setDisabled(false);
        $c.stf.setObjectValue(txb_ONECOM_APPL_RSN_NM, "");
    }
};



