};



/**
 * 트랜잭션 처리 
 */
scwin.fn_trs = function(trsIdx) {
    var VListBzTpCd;
    var param = "";
    var vScrenProcTpCd;

	//----W-Craft WebSquare 변환 확인: NameValue----//
    var listProcsStatCd = dts_info.NameValue(dts_info.RowPosition, "LIST_PROCS_STAT_CD");
    if (scwin.TR_JOB == "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
        listProcsStatCd = "33";
    } else if (scwin.TR_JOB == "U") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
        if (scwin.isSuspn) {
            listProcsStatCd = "11";
        }
        if (scwin.isReSuspn) {

	//----W-Craft WebSquare 변환 확인: NameValue----//
            listProcsStatCd = dts_PROCS_STAT_CD.NameValue(1, "LIST_PROCS_STAT_CD");
        }
    } else if (scwin.TR_JOB == "D") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
    }
    scwin.isStatusUpdate = false;
    trs_Save.Action = $c.lce.fn_encodeNSession("/lstinvstg/KsqSkilValu.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcTpCd + "&method=saveKsqSkilValu");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_info,I:pFile=dts_fileInfo,I:pLeadCom=dts_LeadCom,I:pExcInst=dts_ExecInstList)";
    param = "TRS_IDX=" + trsIdx + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",ISUR_CD=99999" + ",LIST_BZ_TP_CD=760" + ",LIST_PROCS_STAT_CD=" + listProcsStatCd;
    if (scwin.TR_JOB == "I") {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************


	//----W-Craft WebSquare 변환 확인: NameValue----//
        /*ORG SRC: dts_info.NameValue(1, "REG_ID") = js_id;*/
        X = js_id;
    }
    trs_Save.Parameters = param;

	//----W-Craft WebSquare 변환 확인: Post----//
    trs_Save.Post();
};


