    if (scwin.checkFileNameSize(fileName)) {
        return false;
    }
    var txbFileOb = eval("txb_FILE_NM" + fileDiv);
    txbFileOb.value = inf_find.Value;

	//----W-Craft WebSquare 변환 확인: NameValueRow----//

	//----W-Craft WebSquare 변환 확인: NameValue----//
    var fileRow = dts_fileInfo.NameValueRow("FILE_DIV", scwin.fileTpCdarr[fileDiv - 1]);
    if (fileRow > 0) {
        //기존파일 존재

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        /*ORG SRC: dts_fileInfo.NameString(fileRow, "fileInfo") = fileFullPath;*/

	//----W-Craft WebSquare 변환 확인: FileInfo----//
        X = fileFullPath; /*ORG SRC: dts_fileInfo.NameString(fileRow, "fileUrl") = fileFullPath;*/ X = fileFullPath; /*ORG SRC: dts_fileInfo.NameString(fileRow, "ATTACH_FILE_SZ") = inf_find.FileInfo("size");*/ X = inf_find.FileInfo("size"); /*ORG SRC: dts_fileInfo.NameString(dts_fileInfo.CountRow, "FILE_DIV") = fileTpCdarr[fileDiv - 1].substring(0, 2) + fileTpCdarr[fileDiv - 1].substring(2, 3);*/ X = scwin.fileTpCdarr[fileDiv - 1].substring(0, 2) + scwin.fileTpCdarr[fileDiv - 1].substring(2, 3);
    } else {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************


	//----W-Craft WebSquare 변환 확인: AddRow----//

	//----W-Craft WebSquare 변환 확인: FileInfo----//
        dts_fileInfo.AddRow(); /*ORG SRC: dts_fileInfo.NameString(dts_fileInfo.CountRow, "fileInfo") = fileFullPath;*/ X = fileFullPath; /*ORG SRC: dts_fileInfo.NameString(dts_fileInfo.CountRow, "fileUrl") = fileFullPath;*/ X = fileFullPath; /*ORG SRC: dts_fileInfo.NameString(dts_fileInfo.CountRow, "ATTACH_FILE_SZ") = inf_find.FileInfo("size");*/ X = inf_find.FileInfo("size"); /*ORG SRC: dts_fileInfo.NameString(dts_fileInfo.CountRow, "SEQ") = fileTpCdarr[fileDiv - 1].substring(2, 3);*/ X = scwin.fileTpCdarr[fileDiv - 1].substring(2, 3); /*ORG SRC: dts_fileInfo.NameString(dts_fileInfo.CountRow, "SKIL_VALU_ATTACH_FILE_TP_CD") = fileTpCdarr[fileDiv - 1].substring(0, 2);*/ X = scwin.fileTpCdarr[fileDiv - 1].substring(0, 2); /*ORG SRC: dts_fileInfo.NameString(dts_fileInfo.CountRow, "BZ_PROCS_NO") = vBzProcsNo;*/ X = scwin.vBzProcsNo; /*ORG SRC: dts_fileInfo.NameString(dts_fileInfo.CountRow, "FILE_DIV") = fileTpCdarr[fileDiv - 1].substring(0, 2) + fileTpCdarr[fileDiv - 1].substring(2, 3);*/ X = scwin.fileTpCdarr[fileDiv - 1].substring(0, 2) + scwin.fileTpCdarr[fileDiv - 1].substring(2, 3);
        var deleteIcon = eval("file_delete" + fileDiv);
        $c.stf.showObj(deleteIcon, true);
    }
    inf_find.Value = "";
};


/**
 * 파일명 길이 체크
 */
scwin.checkFileNameSize = function(fileName) {
    var nameByte = $c.stf.getStringSize(fileName);
    var overLen = eval(nameByte - 80);
    var isValid = false;
    if (overLen > 0) {
        alert("파일명의 최대길이는 80byte입니다. 파일명 길이를 확인하세요 (한글 : 2 byte 숫자,영문 : 1byte)");
        isValid = true;
    }
    return isValid;
};


/**
 * 평가기관에 선택된 제척기관인지 확인
 */
scwin.fncheckInstCheck = function() {
    var instCd1 = $c.stf.getObjectValue(cmb_SKIL_VALU_INST_CD1);
    var instCd2 = $c.stf.getObjectValue(cmb_SKIL_VALU_INST_CD2);
    var execInstCd;
    for (var i = 1, j = dts_ExecInstList.CountRow; i <= j; i++) {

	//----W-Craft WebSquare 변환 확인: NameValue----//
        execInstCd = dts_ExecInstList.NameValue(i, "SPECY_VALU_INST_CD");
        if (execInstCd != "") {
            if (execInstCd == instCd1 || execInstCd == instCd2) {
                alert("제척기관은 평가기관으로 선택할수 없습니다.");
                return false;
            }
        }
    }
    return true;
};


/**
 * 첨부파일 텍스트박스에 설정
 */

	//----W-Craft WebSquare 변환 확인: FileInfo----//
scwin.fn_setFileInfo = function() {
    var txbFileObj, findRow, fileTpCd, lastName, isTrue;
    var fileDownIcon = "down_file";
    var fileDelIcon = "file_delete";
    for (var i = 1; i <= 23; i++) {
        if (i == 11) continue;
        txbFileObj = eval("txb_FILE_NM" + i);

	//----W-Craft WebSquare 변환 확인: NameValueRow----//

	//----W-Craft WebSquare 변환 확인: NameValue----//
        findRow = dts_fileInfo.NameValueRow("FILE_DIV", scwin.fileTpCdarr[i - 1]);
        var downIcon = eval(fileDownIcon + i);
        var deleteIcon = eval(fileDelIcon + i);
        if (findRow > 0) {

	//----W-Craft WebSquare 변환 확인: NameValue----//
            txbFileObj.value = dts_fileInfo.NameValue(findRow, "ATTACH_FILE_NM");
            isTrue = true;
        } else {
            txbFileObj.value = "";
            isTrue = false;
        }
        $c.stf.showObj(downIcon, isTrue);
        $c.stf.showObj(deleteIcon, isTrue);
    }
};



/**
 * 첨부파일 삭제
 */
scwin.fn_fileDelete = function(fileDiv) {
    var txtFileObj, fileRow;
    txtFileObj = eval("txb_FILE_NM" + fileDiv);
    if (txtFileObj.value == "") {
        return;
    } else {
        if (confirm("파일을 삭제하시겠습니까?")) {
            txtFileObj.value = "";

	//----W-Craft WebSquare 변환 확인: NameValueRow----//

	//----W-Craft WebSquare 변환 확인: NameValue----//
            fileRow = dts_fileInfo.NameValueRow("FILE_DIV", scwin.fileTpCdarr[fileDiv - 1]);
            if (fileRow > 0) {

	//----W-Craft WebSquare 변환 확인: DeleteRow----//
                dts_fileInfo.DeleteRow(fileRow);
            }
        }
    }
};





