        cmb_SPECY_VALU_SKIL_CLSS_CD.enable2 = false;
        cmb_SPECY_VALU_SKIL_CLSS_CD2.enable2 = false;
        $c.stf.setObjectValue(cmb_SPECY_VALU_IND_CLSS_CD, "");
        $c.stf.setObjectValue(cmb_SPECY_VALU_IND_CLSS_CD2, "");
        $c.stf.setObjectValue(cmb_SPECY_VALU_SKIL_CLSS_CD, "");
        $c.stf.setObjectValue(cmb_SPECY_VALU_SKIL_CLSS_CD2, "");
    } else {
