scwin.fn_setBtn = function() {

	//----W-Craft WebSquare 변환 확인: NameValue----//
    var listProcsStatCd = dts_info.NameValue(dts_info.RowPosition, "LIST_PROCS_STAT_CD");

	//----W-Craft WebSquare 변환 확인: NameValue----//
    var retryYn = dts_info.NameValue(dts_info.RowPosition, "RETRY_YN");
    if (listProcsStatCd != "32") {
        btn_Acpt.src = "../img/btn_Acpt_d.gif";
        btn_Acpt.setDisabled(false);
        btn_Reject.src = "../img/btn_reject_d.gif";
        btn_Reject.setDisabled(false);
    }
    if (retryYn == "Y") {
        btn_RETRY_YN.src = "../img/btn_09.gif";
        btn_RETRY_YN.setDisabled(true);
    } else {
        btn_RETRY_YN.src = "../img/btn_09_d.gif";
        btn_RETRY_YN.setDisabled(false);
    }
};



