//철회일이 입력되었는지 체크
scwin.fn_checkSuspnDd = function() {

	//----W-Craft WebSquare 변환 확인: NameValue----//
    var suspnDd = dts_info.NameValue(dts_info.RowPosition, "ASSGN_SUSPN_DD");

	//----W-Craft WebSquare 변환 확인: NameValue----//
    var oriSuspnDd = dts_info.NameValue(dts_info.RowPosition, "ORI_ASSGN_SUSPN_DD");
    if (oriSuspnDd == "" && suspnDd.length == 8) {
        //철회일이 없었는데 새로 입력된 경우
        scwin.isSuspn = true;
    } else {
        scwin.isSuspn = false;
    }
    if (suspnDd == "" && oriSuspnDd.length == 8) {
        //철회일이 있었는데 지운경우
        scwin.isReSuspn = true;
        var url = "/listingCommon.do?method=listGeneralForDynamicName" + "&outputMessageId=SPECY_VALU_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.lstinvstg.specyvalu.bzprocs.select" + "&{P}BZ_PROCS_NO=" + scwin.vBzProcsNo;
        dts_PROCS_STAT_CD.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: reset----//
        dts_PROCS_STAT_CD.reset();
    } else {
        scwin.isReSuspn = false;
    }
};
scwin.dateCheck = function(obj, objName) {
    var date = $c.stf.getObjectValue(obj);
    var validDate = $c.ut.isDate(date);
    if (!validDate) {
        alert(objName + " 유효한 날짜만 입력가능합니다.");
        //edt_SKIL_VALU_ASSGN_DD.focus();

    }
    return validDate;
};
