scwin.trs_Save_OnFail = function() {
    $c.lce.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    if (scwin.isStatusUpdate) {
        $c.lce.fn_alertMsg('S1');
    } else {
        $c.lce.fn_alertMsg('S');
    }
    scwin.fn_parentRefresh();
    if (scwin.TR_JOB == "D") {

	//----W-Craft WebSquare 변환 확인: CloseFrame----//
        frame.CloseFrame();
    } else {
        scwin.fn_commList();
        scwin.fn_fileList();

	//----W-Craft WebSquare 변환 확인: setUpdateStatus----//
        buttonSet.setUpdateStatus();
        scwin.setCmbTxt();
    }
};
scwin.gform_onload = function() {
    scwin.setTrJob();
    scwin.fn_searchCode();
    scwin.fn_grdSearchCode();
    scwin.fn_setSkilValueInstCdCmb();
    //fn_setFileInfo();	
    scwin.fn_grdList();

	//----W-Craft WebSquare 변환 확인: setSaveInfo----//
    buttonSet.setSaveInfo(btn_Save, fn_save);

	//----W-Craft WebSquare 변환 확인: setUpdateInfo----//
    buttonSet.setUpdateInfo(btn_Update, fn_update);

	//----W-Craft WebSquare 변환 확인: setDeleteInfo----//
    buttonSet.setDeleteInfo(btn_Delete, fn_delete);
    if (scwin.TR_JOB != "I") {
        scwin.fn_commList();
        scwin.fn_fileList();

	//----W-Craft WebSquare 변환 확인: setUpdateStatus----//
        buttonSet.setUpdateStatus();
    } else {
        //기본정보 데이터셋 초기화
        dts_info.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=SPECY_VALU_INOUT";

	//----W-Craft WebSquare 변환 확인: reset----//
        dts_info.reset();

	//----W-Craft WebSquare 변환 확인: AddRow----//
        dts_info.AddRow();
        $c.stf.setObjectValue(rdo_SKIL_BZ_TP_CD, "01");
        $c.stf.setObjectValue(rdo_VALU_INST_APPL_CNT, "2");
        //첨부파일 데이터셋 초기화
        dts_fileInfo.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=KSQ_SKIL_VALU_FILE_INOUT";

	//----W-Craft WebSquare 변환 확인: reset----//
        dts_fileInfo.reset();

	//----W-Craft WebSquare 변환 확인: setInsertStatus----//
        buttonSet.setInsertStatus();
    }
    scwin.setCmbTxt();
};
